    raise exception 'a supply, vendor-value, ability-rune or login-reward row names an item hr_items does not have'; end if;
  if exists (select 1 from public.hr_hunt_travel t where not t.training
               and not exists (select 1 from public.hr_hunts h where h.hunt_id = t.hunt_id))
     or exists (select 1 from public.hr_hunt_grounds g where not exists (select 1 from public.hr_hunts h where h.hunt_id = g.hunt_id)) then
    raise exception 'a named hunt or a ground hunt is not in hr_hunts'; end if;
  if exists (select 1 from public.hr_hunt_travel t where t.training
               and not exists (select 1 from public.hr_activities a
                                where a.kind = 'combat' and a.activity_id = t.hunt_id and not a.is_boss)) then
    raise exception 'a training id in hr_hunt_travel is not a non-boss combat target'; end if;
  if exists (select 1 from public.hr_hunt_ground_spawns s
               where not exists (select 1 from public.hr_hunt_kill_bounds b where b.monster_id = s.monster_id)) then
    raise exception 'a ground spawns a monster with no kill bound'; end if;
  -- The Magic-XP bound covers the biggest store drink at one drink a consumable lane (else a settle that
  -- drank the basics it bought is refused as over-bound).
  if public.hr_hunt_limit('drink_mana_per_min_max')
       < (60000 / (select ms from public.hr_hunt_lanes where lane = 'consumable'))
         * (select coalesce(max(mana), 0) from public.hr_hunt_basic_supplies where kind = 'mana') then
    raise exception 'drink_mana_per_min_max is under the store drinks at one per consumable lane'; end if;
  -- No client role reads or writes any of them; no policy exists.
  foreach v_role in array array['anon', 'authenticated'] loop
    foreach v_t in array array['hr_hunt_supplies', 'hr_hunt_travel', 'hr_hunt_limits', 'hr_hunt_end_reasons', 'hr_hunt_vendor_value', 'hr_hunt_target_modes', 'hr_hunt_resumable_kinds', 'hr_hunt_basic_supplies', 'hr_hunt_cover_items', 'hr_hunt_lanes', 'hr_hunt_set_options', 'hr_hunt_kill_bounds', 'hr_hunt_abilities', 'hr_hunt_grounds', 'hr_hunt_ground_spawns', 'hr_hunt_world_shape', 'hr_premium_login_reward', 'hr_hunt_roster', 'hr_hunt_weapons', 'hr_hunt_weapon_roles', 'hr_hunt_roles'] loop
      if has_table_privilege(v_role, 'public.' || v_t, 'select,insert,update,delete,truncate') then
        raise exception '% holds a privilege on %', v_role, v_t; end if;
    end loop;
  end loop;
  if exists (select 1 from pg_policies where schemaname = 'public' and tablename in ('hr_hunt_supplies', 'hr_hunt_travel', 'hr_hunt_limits', 'hr_hunt_end_reasons', 'hr_hunt_vendor_value', 'hr_hunt_target_modes', 'hr_hunt_resumable_kinds', 'hr_hunt_basic_supplies', 'hr_hunt_cover_items', 'hr_hunt_lanes', 'hr_hunt_set_options', 'hr_hunt_kill_bounds', 'hr_hunt_abilities', 'hr_hunt_grounds', 'hr_hunt_ground_spawns', 'hr_hunt_world_shape', 'hr_premium_login_reward', 'hr_hunt_roster', 'hr_hunt_weapons', 'hr_hunt_weapon_roles', 'hr_hunt_roles')) then
    raise exception 'a policy exists on the hunt-session catalogue'; end if;
end $$;
